<section class="card overview-main" aria-labelledby="overview-movers-heading">
<div class="card-header"><div><p class="integration-kicker">Performance evidence</p><h2 id="overview-movers-heading">What moved</h2></div><a class="small" href="<?= $view->e($base . '/performance?range=' . $rangeKey) ?>">Performance →</a></div>
<?php if (!$evidence['comparable']): ?><p class="muted">Comparison unavailable. Query/page imports cover <?= $evidence['covered'] ?> / <?= $evidence['range']->days() ?> current days and <?= $evidence['previousCovered'] ?> / <?= $evidence['range']->days() ?> previous days.</p><a href="<?= $view->e($base) ?>/performance">Check import coverage</a>
<?php else: ?>
<p class="muted small">Google · <?= $view->e($evidence['range']->fromString()) ?> – <?= $view->e($evidence['range']->toString()) ?> vs <?= $view->e($evidence['range']->previous()->fromString()) ?> – <?= $view->e($evidence['range']->previous()->toString()) ?></p>
<?php foreach (['query' => 'Queries', 'page' => 'Pages'] as $kind => $label): $data = $evidence['movers'][$kind]; ?>
<details class="overview-mover-group" open><summary><?= $view->e($label) ?><span class="muted small"><?= number_format($data['total']) ?> comparable rows</span></summary>
<div class="table-scroll"><table class="table table-dense" data-no-table-controls><thead><tr><th scope="col"><?= $kind === 'query' ? 'Query' : 'Page' ?></th><th scope="col" class="num">Clicks</th><th scope="col" class="num">Δ clicks</th><th scope="col" class="num">Impressions</th><th scope="col" class="num">CTR</th><th scope="col" class="num">Position</th></tr></thead><tbody>
<?php foreach (['gainers' => 'Gaining clicks', 'losers' => 'Losing clicks'] as $direction => $heading): ?>
<tr class="overview-table-group overview-<?= $view->e($direction) ?>"><th colspan="6" scope="rowgroup"><?= $view->e($heading) ?></th></tr>
<?php foreach ($data[$direction] as $row): $now = $row['current']; $before = $row['previous']; ?>
<tr><td class="overview-subject"><?php if ($kind === 'page'): ?><a title="<?= $view->e($row['key']) ?>" href="<?= $view->e($base . '/pages/details?url=' . rawurlencode($row['key'])) ?>"><?= $view->e(preg_replace('#^https?://[^/]+#', '', $row['key']) ?: '/') ?></a><?php else: ?><?= $view->e($row['key']) ?><?php endif; ?></td><td class="num"><?= number_format($now->clicks) ?><span class="overview-cell-note">was <?= number_format($before->clicks) ?></span></td><td class="num <?= $row['delta'] > 0 ? 'delta-good' : 'delta-bad' ?>"><?= sprintf('%+d', $row['delta']) ?><span class="overview-cell-note"><?= $row['percent'] === null ? 'from zero recorded clicks' : $view->e(sprintf('%+.1f %%', $row['percent'])) ?></span></td><td class="num"><?= number_format($now->impressions) ?><span class="overview-cell-note"><?= sprintf('%+d', $now->impressions - $before->impressions) ?></span></td><td class="num"><?= $now->impressions > 0 ? number_format($now->ctr() * 100, 1) . ' %' : '—' ?><span class="overview-cell-note"><?= $now->impressions > 0 && $before->impressions > 0 ? sprintf('%+.1f pp', ($now->ctr() - $before->ctr()) * 100) : '—' ?></span></td><td class="num"><?= $now->impressions > 0 ? number_format($now->position, 1) : '—' ?><span class="overview-cell-note"><?= $now->impressions > 0 && $before->impressions > 0 ? sprintf('%+.1f', $now->position - $before->position) : '—' ?></span></td></tr>
<?php endforeach; ?>
<?php if ($data[$direction] === []): ?><tr><td colspan="6" class="muted">No <?= $view->e(strtolower($heading)) ?> among the comparable rows returned.</td></tr><?php endif; ?>
<?php endforeach; ?></tbody></table></div>
</details>
<?php endforeach; ?>
<details class="overview-about"><summary><?= $view->icon('info') ?>About this data</summary><p>Only rows observed in both periods; absent rows are not measured zeros.</p><?php foreach (['query' => 'Queries', 'page' => 'Pages'] as $kind => $label): $data = $evidence['movers'][$kind]; ?><p><?= $view->e($label) ?>: read <?= $data['loaded'] ?> of <?= number_format($data['total']) ?> matched rows, balanced across gains, losses and unchanged rows, taking the largest movements in each group. Up to three gainers and losers shown.</p><?php endforeach; ?></details>
<?php endif; ?>
</section>
